                          for r in range(4)))

    def rotations(shape):
        result = []
        cur = shape
        for _ in range(4):
            result.append(cur)
            cur = tuple(tuple(cur[3 - c][r] for c in range(4)) for r in range(4))
        return result

    # Color instances that have another matching panel under rotation.
    seen = set()
    for i, shape in enumerate(sigs):
        if i in seen:
            continue
        group = [j for j, other in enumerate(sigs)
                 if other in rotations(shape)]
        seen.update(group)
        if len(group) < 2:
